NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, Apostel Christi Jesu, gemäß dem Auftrag Gottes, unseres Heilandes und Christi Jesu, unserer Hoffnung,',
        2: 'an Timotheus, sein echtes Kind im Glauben. Gnade, Barmherzigkeit und Friede werde dir zuteil von Gott, dem Vater, und von Christus Jesus, unserem Herrn.',
        3: 'Als ich nach Mazedonien reiste, bat ich dich, in Ephesus zu bleiben. Du solltest da gewissen Leuten einschärfen, sie möchten nicht anders lehren,',
        4: 'auch nicht mit Fabeln und endlosen Geschlechtsregistern sich abgeben. Derlei Dinge fördern mehr Grübeleien als Gottes Heilsordnung, die auf dem Glauben ruht.',
        5: 'Das Ziel der Predigt ist aber Liebe aus reinem Herzen, aus trefflichem Gewissen, aus ungeheucheltem Glauben.',
        6: 'Doch eben davon sind gewisse Leute abgekommen und auf eitle Schwätzereien verfallen.',
        7: 'So wollen sie Gesetzeslehrer sein; doch sie verstehen nicht, was sie sagen, noch was sie so kühn behaupten.',
        8: 'Wir wissen: Gut ist das Gesetz, nur muß man es richtig anwenden',
        9: 'und sich dabei bewußt bleiben, daß es nicht dem Gerechten gilt, sondern für Frevler, Unbotmäßige, Gottlose, Sünder, Unheilige, Gemeine, für Vatermörder und Muttermörder, Totschläger,',
        10: 'für Huren, Knabenschänder, Menschenhändler, Lügner und Meineidige und was sonst noch der gesunden Lehre widerstrebt.',
        11: 'So lehrt das Evangelium der Herrlichkeit des seligen Gottes, mit dem ich beauftragt bin.',
        12: 'Dank weiß ich Christus Jesus, unserem Herrn, der mir Kraft gegeben hat, daß er mich für vertrauenswürdig hielt und mich zum Dienst bestellte,',
        13: 'mich, der ich früher selbst Lästerer, Verfolger und Bedrücker war. Allein, ich fand Erbarmen, weil ich unwissend gehandelt hatte, als ich noch nicht gläubig war.',
        14: 'Doch überreichlich ward die Gnade unseres Herrn mit Glaube und mit Liebe in Christus Jesus.',
        15: 'Dieses Wort ist wahr und wohl wert, daß es überall angenommen werde: Christus Jesus kam in die Welt, die Sünder zu erretten. Von ihnen bin ich der erste.',
        16: 'Gerade darum fand ich auch Erbarmen, damit an mir, als an dem ersten, Jesus Christus seine ganze Langmut zeige, ein Vorbild derer, die an ihn glauben und dadurch zum ewigen Leben gelangen werden.',
        17: 'Dem Könige der Ewigkeiten, dem unsterblichen, unsichtbaren, einzigen Gott sei Ruhm und Herrlichkeit in Ewigkeit der Ewigkeiten. Amen.',
        18: 'Ich lege dir nun diese Predigt ans Herz, mein Kind Timotheus, entsprechend den Weissagungen, die auf dich hinzielten, daß du in ihrer Kraft den guten Kampf durchkämpfest.',
        19: 'Halte dabei fest den Glauben und ein gutes Gewissen, das einige schon weggeworfen haben und so am Glauben Schiffbruch litten.',
        20: 'Darunter sind Hymenäus und Alexander. Ich habe sie dem Satan überantwortet, damit sie das Lästern verlernen.',
    },
    2: {
        1: 'Vor allen Dingen dringe ich darauf, daß Gebete, Bitten, Fürbitten sowie Danksagungen verrichtet werden für alle Menschen,',
        2: 'für Könige und jede Obrigkeit, damit wir ein stilles und ruhiges Leben führen in jeglicher Gottseligkeit und Ehrbarkeit.',
        3: 'So ist es gut und wohlgefällig vor unserem Heiland-Gott,',
        4: 'der will, daß alle Menschen Rettung finden und zur Einsicht in die Wahrheit kommen.',
        5: 'Es gibt nur einen Gott und einen Mittler zwischen Gott und Menschen, den Menschen Christus Jesus.',
        6: 'Er gab sich selbst als Lösegeld für alle hin; zur rechten Zeit ein Zeugnis.',
        7: 'Dafür bin ich zum Herold und Apostel aufgestellt - ich sage die Wahrheit und lüge nicht -, in ewiger Treue zum Völkerlehrer.',
        8: 'Ferner will ich, daß, wo immer die Männer beten, sie heilige Hände erheben ohne Zorn und zweifelnde Bedenken.',
        9: 'Desgleichen, daß die Frauen in sittsamer Haltung mit Zucht sich schmücken und mit edlem Anstand und nicht mit Haargeflecht, Gold, Perlen oder mit kostbaren Gewändern,',
        10: 'sondern, wie es sich für Frauen ziemt, die fromm sein wollen, mit guten Werken.',
        11: 'Das Weib soll in aller Unterwürfigkeit und Ruhe lernen.',
        12: 'Zu lehren gestatte ich dem Weibe nicht; auch nicht, dem Manne zu befehlen; sie soll sich zurückhaltend zeigen.',
        13: 'Denn Adam ward zuerst erschaffen und dann erst Eva.',
        14: 'Auch ließ nicht Adam sich betören; wohl aber ließ sich das Weib völlig betören und kam zu Fall.',
        15: 'Das Heil erlangt sie aber durch Kindergebären, wenn sie ausharrt im Glauben, in der Liebe und in der Heiligung ihrer selbst in einem sittsamen Betragen.',
    },
    3: {
        1: 'Es ist ein wahres Wort - Wer nach dem Bischofsamt strebt, begehrt ein herrliches Ding.',
        2: 'Doch muß der Bischof untadelig sein, nur einmal verheiratet, nüchtern, besonnen, sittsam, gastfreundlich und lehrtüchtig,',
        3: 'nicht dem Trunk ergeben, nicht gewalttätig, im Gegenteil gefällig, nicht streitsüchtig, nicht geldgierig.',
        4: 'Er muß imstande sein, dem eigenen Hause wohl vorzustehen und seine Kinder im Gehorsam und in aller Sittsamkeit zu halten.',
        5: 'Denn wer sein eigenes Haus nicht zu verwalten weiß, wie sollte der für die Kirche Gottes Sorge tragen können?',
        6: 'Er darf kein Neugetaufter sein, damit er nicht hochmütig werde und ins Gericht des Teufels falle.',
        7: 'Endlich muß er ein gutes Zeugnis haben von den Außenstehenden, damit er nicht in üble Nachrede komme und in die Schlinge des Teufels.',
        8: 'Auch die Diakone müssen ehrbar sein, nicht doppelzüngig, sie dürfen nicht reichlichem Weingenuß und schändlichem Verdienst ergeben sein.',
        9: 'Sie müssen das Geheimnis des Glaubens in reinem Gewissen bewahren.',
        10: 'Auch diese sollen vorher der Prüfung unterzogen werden und erst dann das Amt ausüben, wenn sie unbescholten sind.',
        11: 'Ebenso sollen die Frauen ehrbar sein und nicht verleumderisch, sondern nüchtern und in allem zuverlässig.',
        12: 'Die Diakone dürfen nur einmal verheiratet sein; sie sollen ihren Kindern und dem Hauswesen gut vorstehen.',
        13: 'Denn solche, die das Amt des Diakons gut verwaltet haben, erwerben sich eine schöne Stellung und viel Zuversicht im Glauben an Christus Jesus.',
        14: 'Das schreibe ich dir, voll Hoffnung, recht bald zu dir zu kommen.',
        15: 'Doch sollte meine Ankunft sich verzögern, so sollst du wissen, wie man sich im Hause Gottes zu benehmen hat; denn die Kirche des lebendigen Gottes ist eine Säule und Grundfeste der Wahrheit.',
        16: 'Groß ist, wie jeder zugesteht, das Geheimnis der Frömmigkeit: Er, der im Fleische geoffenbart wurde, ward im Geiste gerechtfertigt; er wurde kundgetan den Engeln, verkündet bei den Völkern, in der Welt geglaubt, hinaufgenommen in Herrlichkeit.',
    },
    4: {
        1: 'Der Geist sagt bestimmt, daß in den künftigen Zeiten manche vom Glauben abfallen und Irrgeistern und Lehren von den Dämonen sich hingeben werden,',
        2: 'Menschen, die mit heuchlerischem Sinne Lügen reden und die an ihrem eigenen Gewissen gebrandmarkt sind,',
        3: 'Menschen, die das Heiraten verbieten und den Genuß gewisser Speisen, die Gott geschaffen hat, damit sie von den Gläubigen, die die Wahrheit erkannt haben, mit Danksagung genossen würden.',
        4: 'Denn alles, was Gott geschaffen hat, ist gut und nichts verwerflich, wenn es nur mit Danksagung genossen wird.',
        5: 'Geheiligt wird es ja durch das Wort Gottes und durch Gebet.',
        6: 'Wenn du dies den Brüdern ans Herz legst, dann wirst du ein guter Diener Christi Jesu sein, der sich an den Worten des Glaubens und an der rechten Lehre nährt; sie hast du dir ja zur Richtschnur genommen.',
        7: 'Altweiberfabeln aber und Albernheiten weise ab; übe dich vielmehr für die Frömmigkeit.',
        8: 'Die Leibesübung bringt wenig Nutzen, die Frömmigkeit dagegen ist zu allem nützlich, weil sie die Verheißung hat für dieses Leben und für das künftige.',
        9: 'Dies Wort ist wahr und wohl wert, daß es allgemein angenommen werde.',
        10: 'Denn dafür mühen wir uns ab und kämpfen wir, weil wir unsere Hoffnung auf den lebendigen Gott gesetzt haben, den Retter aller Menschen, vor allem der Gläubigen.',
        11: 'Dies sollst du einschärfen und lehren.',
        12: 'Niemand schätze dich deiner Jugend wegen gering. Sei vielmehr ein Vorbild für die Gläubigen im Wort, im Wandel, in Liebe, im Glauben, in der Reinheit.',
        13: 'Bis ich komme, widme dich der Vorlesung, dem Ermahnen und dem Lehren.',
        14: 'Achte die Gnadengabe in dir nicht gering, die dir verliehen ward zufolge Weissagung und unter der Handauflegung des Presbyteriums.',
        15: 'Nimm dies zu Herzen, gehe ganz darin auf, damit dein Fortschritt allen offenkundig sei.',
        16: 'Achte auf dich selbst und auf die Lehre, halte daran fest. Denn wenn du dies tust, wirst du dich selbst und deine Hörer retten.',
    },
    5: {
        1: 'Einen alten Mann sollst du nicht schroff anfahren, sondern rede ihm wie einem Vater zu; den jüngeren Männern rede zu wie Brüdern;',
        2: 'den älteren Frauen wie Müttern; den jüngeren in aller Ehrbarkeit wie Schwestern.',
        3: 'Witwen, die echte Witwen sind, ehre!',
        4: 'Wenn aber eine Witwe Kinder oder Enkel hat, so sollen diese es zunächst lernen, die eigene Familie liebevoll zu behandeln und so sich den Vorfahren dankbar zu erweisen; denn das ist vor Gott wohlgefällig.',
        5: 'Die wahre Witwe, die vereinsamt ist, hat ihre Hoffnung in Gott und verharrt in Gebet und Flehen Tag und Nacht.',
        6: 'Lebt aber eine ausschweifend, so ist sie lebend tot.',
        7: 'Dies schärfe ein, damit sie untadelig seien.',
        8: 'Wer aber für die Seinen, zumal für seine Angehörigen, nicht Sorge trägt, der hat den Glauben verleugnet und ist schlimmer als ein Ungläubiger.',
        9: 'Als Witwe soll nur jene ins Verzeichnis eingetragen werden, die wenigstens schon sechzig Jahre alt und nur einmal verheiratet gewesen ist,',
        10: 'im Rufe guter Werke steht, wenn sie ihre Kinder gut erzogen, Gastfreundschaft ausgeübt, den Heiligen die Füße gewaschen, Bedrängten Hilfe geleistet und aller guten Werke sich befleißigt hat.',
        11: 'Jüngere Witwen weise ab. Wenn sie Christus zuwider sinnlich werden,',
        12: 'so wollen sie heiraten und ziehen sich ein Gericht zu, weil sie die erste Treue brachen.',
        13: 'Zugleich lernen sie, müßig in den Häusern herumzulaufen, ja, nicht nur müßig, sondern auch geschwätzig und recht vorwitzig, wobei sie ungeziemend reden.',
        14: 'Deswegen will ich auch, daß Jüngere wieder heiraten, Kinder gebären und den Haushalt führen und so dem Gegner keinen Anlaß zu übler Nachrede geben.',
        15: 'Denn schon sind etliche dem Satan nach vom rechten Weg abgewichen.',
        16: 'Wenn eine Christin Witwen bei sich hat, so soll sie auch für diese sorgen; nicht aber die Gemeinde noch damit belasten, auf daß diese die eigentlichen Witwen versorgen kann.',
        17: 'Die Presbyter, die ihr Amt gut verwalten, erachte man zweifacher Ehre wert; vorzüglich jene, die in Wort und Lehre sich mühen.',
        18: 'Sagt doch die Schrift: "Dem dreschenden Ochsen sollst du das Maul nicht verbinden", und: "Der Arbeiter ist seines Lohnes wert."',
        19: 'Nimm gegen einen Presbyter keine Klage an, außer auf Grund von zwei oder drei Zeugen.',
        20: 'Die Fehlenden weise in der Gegenwart aller zurecht, damit auch die anderen Furcht bekommen.',
        21: 'Ich beschwöre dich vor Gott, vor Christus Jesus und den auserwählten Engeln: Befolge dies ohne Vorurteil und handle nicht nach Gunst.',
        22: 'Lege niemand vorschnell die Hände auf und mache dich fremder Sünde nicht mitschuldig. Dich selber halte rein.',
        23: 'Trinke nicht mehr ausschließlich Wasser; genieße auch ein wenig Wein, deines Magens und deiner vielen Schwächen wegen.',
        24: 'Bei manchen Menschen sind die Sünden offenkundig und eilen dem Gerichte voraus; bei anderen folgen sie erst nach.',
        25: 'Genauso sind die guten Werke offenbar; und auch, wo es sich anders verhält, können sie nicht verborgen bleiben.',
    },
    6: {
        1: 'Alle, die das Joch des Sklaven tragen, sollen ihre Herren aller Ehre würdig halten, auf daß der Name Gottes und die Lehre nicht gelästert werden.',
        2: 'Die aber Gläubige zu Herren haben, sollen sie deshalb nicht für gering erachten, weil sie Brüder sind, vielmehr nur um so williger ihnen dienen, weil sie Gläubige und Geliebte sind, die sich des Wohltuns befleißigen. Dies lehre und schärfe ein!',
        3: 'Wer anders lehrt und sich nicht an die gesunden Worte unseres Herrn Jesus Christus hält und nicht an die Lehre, die der Frömmigkeit entsprechend ist,',
        4: 'der ist verblendet und versteht nichts, sondern krankt an Grübelei und Zanksucht. Daraus entstehen Neid, Streit, Lästerungen, böser Argwohn,',
        5: 'Reibereien unter Menschen, die verdorben sind in ihrem Denken und die den Sinn für die Wahrheit verloren haben, Menschen, die meinen, die Frömmigkeit sei eine Quelle des Erwerbs.',
        6: 'Ja, Frömmigkeit ist eine gute Quelle des Erwerbs, dann, wenn sie mit Genügsamkeit verbunden ist.',
        7: 'Wir haben nichts in diese Welt hereingebracht und können auch nichts mit hinausnehmen.',
        8: 'Wenn wir Nahrung und Kleidung haben, lasset uns damit zufrieden sein.',
        9: 'Die aber danach trachten, reich zu werden, fallen in Versuchung und in Schlingen des Teufels, in viele sinnlose und schädliche Begierden, die die Menschen in Verderben und Untergang stürzen.',
        10: 'Die Liebe zum Geld ist eine Wurzel aller Übel. Manche sind schon in dem Trachten danach vom Glauben abgeirrt und haben sich selber viele Schmerzen zugezogen.',
        11: 'Du aber, Mann Gottes, fliehe dies! Strebe vielmehr nach Gerechtigkeit, Frömmigkeit, Glauben, Liebe, Geduld und Sanftmut.',
        12: 'Kämpfe den guten Kampf des Glaubens; ergreife das ewige Leben, zu dem du berufen bist, für das du vor vielen Zeugen das herrliche Bekenntnis abgelegt hast.',
        13: 'Vor Gott, der allen Dingen Leben gibt, sowie vor Christus Jesus, der unter Pontius Pilatus das herrliche Bekenntnis abgelegt hat, gebiete ich dir:',
        14: 'Bewahre unbefleckt und ohne Tadel dein Amt bis zum Erscheinen unseres Herrn Jesus Christus.',
        15: 'Zur rechten Zeit wird es der selige, alleinige Gebieter kundtun, der König der Könige, der Herr der Herrscher,',
        16: 'der allein Unsterblichkeit besitzt und in einem unzugänglichen Lichte wohnt, den nie ein Mensch gesehen hat, noch sehen kann. Ihm sei Preis und Macht in Ewigkeit. Amen.',
        17: 'Den Reichen dieser Welt gebiete, sich nicht zu überheben und nicht auf ungewissen Reichtum zu vertrauen, vielmehr auf Gott, der alles reichlich zum Genuß uns darreicht.',
        18: 'Sie sollen Gutes tun, an guten Werken reich werden, freigebig und mitteilsam sein',
        19: 'und also eine feste Grundlage für die Zukunft sich zusammentragen, damit sie für sich das wahre Leben erlangen.',
        20: 'Timotheus! Bewahre das anvertraute Gut! Vermeide leeres, unheiliges Geschwätz sowie die Streitfragen der fälschlich sogenannten "Erkenntnis".',
        21: 'Einige, die sich dazu bekannt haben, sind am Glauben irre geworden. Die Gnade sei mit euch.',
    },
}
